float sdRoundedCylinder( vec3 p, float ra, float rb, float h )
{
  vec2 d = vec2( length(p.xz)-2.0*ra+rb, abs(p.y) - h );
  return min(max(d.x,d.y),0.0) + length(max(d,0.0)) - rb;
}
float sdf(in vec3 p, in int s) {
    int state = s&15;
    int rnd = s>>4;
    p -= 0.5;
    float dist = 10000.0;
    if (state == 3) dist = min(dist, length(vec2(length(p.xy-0.4)-0.4, p.z))-0.15);
    if (state == 6) dist = min(dist, length(vec2(length(p.xy-vec2(0.4, -0.4))-0.4, p.z))-0.15);
    if (state == 9) dist = min(dist, length(vec2(length(p.xy-vec2(-0.4, 0.4))-0.4, p.z))-0.15);
    if (state == 12) dist = min(dist, length(vec2(length(p.xy-vec2(-0.4, -0.4))-0.4, p.z))-0.15);
    if (state == 15) {
        float s = sign(float(rnd-8)-0.001);
        dist = min(dist, length(vec2(length(p.xy-vec2(-0.4*s, -0.4))-0.4, p.z))-0.15);
        dist = min(dist, length(vec2(length(p.xy-vec2(0.4*s, 0.4))-0.4, p.z))-0.15);
    }
    if ((state & 1) == 1) dist = min(dist, sdRoundedCylinder(vec3(p.x, p.y, p.z)-vec3(0, 0.45, 0), 0.1, 0.02, 0.03));
    if ((state & 2) == 2) dist = min(dist, sdRoundedCylinder(vec3(p.y, p.x, p.z)-vec3(0, 0.45, 0), 0.1, 0.02, 0.03));
    if ((state & 4) == 4) dist = min(dist, sdRoundedCylinder(vec3(p.x, p.y, p.z)+vec3(0, 0.45, 0), 0.1, 0.02, 0.03));
    if ((state & 8) == 8) dist = min(dist, sdRoundedCylinder(vec3(p.y, p.x, p.z)+vec3(0, 0.45, 0), 0.1, 0.02, 0.03));
    if (state == 7) {
        dist = min(dist, length(p.xz)-0.15);
        dist = min(dist, max(length(p.yz)-0.15, -p.x));
    }
    if (state == 14) {
        dist = min(dist, length(p.yz)-0.15);
        dist = min(dist, max(length(p.xz)-0.15, p.y));
    }
    if (state == 13) {
        dist = min(dist, length(p.xz)-0.15);
        dist = min(dist, max(length(p.yz)-0.15, p.x));
    }
    if (state == 11) {
        dist = min(dist, length(p.yz)-0.15);
        dist = min(dist, max(length(p.xz)-0.15, -p.y));
    }
    if (state == 5) dist = min(dist, length(p.xz)-0.15);
    if (state == 10) dist = min(dist, length(p.yz)-0.15);
    if (state == 1 || state == 2 || state == 4 || state == 8) dist = min(dist, sdRoundedCylinder(vec3(p.x, p.z, p.y)-vec3(0, -0.45, 0), 0.1, 0.02, 0.03));
    if (state == 4) dist = min(dist, length(vec2(length(p.zy-vec2(-0.4, -0.4))-0.4, p.x))-0.15);
    if (state == 2) dist = min(dist, length(vec2(length(p.zx-vec2(-0.4, 0.4))-0.4, p.y))-0.15);
    if (state == 1) dist = min(dist, length(vec2(length(p.zy-vec2(-0.4, 0.4))-0.4, p.x))-0.15);
    if (state == 8) dist = min(dist, length(vec2(length(p.zx-vec2(-0.4, -0.4))-0.4, p.y))-0.15);
    return dist;
}
vec3 getNormal(in vec3 p, in int state) {
    float eps = 0.01;
    return normalize(vec3(
        sdf(vec3(p.x+eps, p.y, p.z), state)-sdf(vec3(p.x-eps, p.y, p.z), state),
        sdf(vec3(p.x, p.y+eps, p.z), state)-sdf(vec3(p.x, p.y-eps, p.z), state),
        sdf(vec3(p.x, p.y, p.z+eps), state)-sdf(vec3(p.x, p.y, p.z-eps), state)
    ));
}
float backgroundHeight(in vec2 p) {
    p = fract(p*3.0)-0.5;
    return max(abs(p.x*p.x*p.x), abs(p.y*p.y*p.y))*length(p)*5.0;
}
vec3 colorTile(in vec2 uv, in int state) {
    vec3 ro = vec3(uv, 0.7);
    vec3 rd = vec3(0, 0.0, -1);
    float dist = 0.0;
    vec3 normal;
    for (int i = 0; i < 100; i++) {
        float d = sdf(ro+rd*dist, state);
        dist += d;
        if (dist > 1.) {
            normal = normalize(vec3(
                backgroundHeight(vec2(uv.x+0.01, uv.y))-backgroundHeight(vec2(uv.x-0.01, uv.y)),
                backgroundHeight(vec2(uv.x, uv.y+0.01))-backgroundHeight(vec2(uv.x, uv.y-0.01)),
                0.1
            ));
            vec3 ref = reflect(rd, normal);
            vec3 light = normalize(vec3(1, 2, 0.5));
            return vec3(1.-exp(-(pow(dot(ref, light)*0.5+0.5, 3.0)+(dot(normal, light)*0.5+0.5))*0.03));
        }
        if (d < 0.01) {
            normal = getNormal(ro+rd*dist, state);
            break;
        }
    }
    vec3 color = vec3(0);
    color += clamp(dot(normal, normalize(vec3(1, 2, 0.5)))*0.5+0.5, 0.0, 1.0)*vec3(0.6, 0.5, 0.5)*0.5;
    color += pow(dot(reflect(vec3(0, 0, -1), normal), normalize(vec3(3, 2, 1)))*0.5+0.5, 10.0)*vec3(0.5, 0.5, 1);
    color += pow(dot(reflect(vec3(0, 0, -1), normal), normalize(vec3(-3, 2, 1)))*0.5+0.5, 10.0)*vec3(0., 0.2, 0.);
    return 1.-exp(-color);
}
