int cellHash(in ivec3 pos) {
    if (pos.x < 0 || pos.x > 2 || pos.y < 0 || pos.y > 2) return 0;
    return int(floor(hash13(uvec3(pos))*16.))|r[int(floor(hash13(uvec3(pos))*6.))];
}
int baseHash(in ivec2 pos) {
    return r[int(floor(hash12(uvec2(pos))*6.))];
}
int getCells(inout vec2 uv,in int base, in int depth, out ivec2 cell) {
    cell = ivec2(floor(uv*3.0));
    uv = fract(uv*3.0);
    int idx = cell.x+3*cell.y;
    if (idx%2 == 1) {
        int h = cellHash(ivec3(cell, depth));
        int bit = cell.y==2?1:(cell.x==2?2:(cell.y==0?4:(cell.x==0?8:0)));
        h = h&(~bit);
        h = h | (base & bit);
        return h;
    }
    int up = cellHash(ivec3(cell+ivec2(0, 1), depth));
    int down = cellHash(ivec3(cell+ivec2(0, -1), depth));
    int left = cellHash(ivec3(cell+ivec2(-1, 0), depth));
    int right = cellHash(ivec3(cell+ivec2(1, 0), depth));

    int state = (up>>2)&1;
    state |= ((right>>3)&1)<<1;
    state |= ((down)&1)<<2;
    state |= ((left>>1)&1)<<3;
    return state;
}
vec3 getColor(in vec2 uv) {
    ivec2 cell = ivec2(floor(uv));
    uv = fract(uv);
    int base;
    int rnd = 0;
    if (((cell.x+cell.y)&1) == 0) {
        base = baseHash(cell);
    } else {
        int up = baseHash(cell+ivec2(0, 1));
        int down = baseHash(cell+ivec2(0, -1));
        int left = baseHash(cell+ivec2(-1, 0));
        int right = baseHash(cell+ivec2(1, 0));

        base = (up>>2)&1;
        base |= ((right>>3)&1)<<1;
        base |= ((down)&1)<<2;
        base |= ((left>>1)&1)<<3;
    }
    rnd = base+cell.x+cell.y*100;
    int scale = 1;
    for (int depth = 1; depth < 5; depth++) {
        base = getCells(uv, base, rnd, cell);
        scale *= 3;
        rnd += (cell.x+cell.y*3)*scale+depth*scale*3;
        rnd = rnd%261;
    }
    base = base | (int(hash11(uint(rnd))*16.)<<4);
    return colorTile(uv, base);
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord.xy)/iResolution.y*0.5;
    uv += (iTime*vec2(0.1, 0.2))*0.5;
    fragColor = vec4(getColor(uv*0.125), 1);
}

